import { Component, computed, input } from '@angular/core';

/** 1 phần trong thanh phân bố. color = token/màu tuỳ chọn (mặc định xoay vòng bảng màu dữ liệu). */
export interface HrmCategorySegment {
  label: string;
  value: number;
  color?: string;
}

/** hrm-category-bar — MỘT thanh ngang chia phần theo tỉ lệ + chú giải: cơ cấu nhân sự
 *  (chính thức/thử việc/thời vụ), phân bố giới tính. Tổng các phần = 100% thanh. */
@Component({
  selector: 'hrm-category-bar',
  template: `
    <div class="cb-bar">
      @for (s of segs(); track s.label) {
        <div class="cb-seg" [style.flex-grow]="s.value" [style.background]="s.color"></div>
      }
    </div>
    @if (showLegend()) {
      <div class="cb-legend">
        @for (s of segs(); track s.label) {
          <span class="cb-item">
            <span class="cb-dot" [style.background]="s.color"></span>
            <span class="cb-lbl">{{ s.label }}</span>
            <span class="cb-pct">{{ s.pct }}%</span>
          </span>
        }
      </div>
    }
  `,
  host: { class: 'hrm-category-bar' },
  styles: [`
:host { display: flex; flex-direction: column; gap: 10px; width: 100%; }
.cb-bar { display: flex; height: 12px; border-radius: var(--radius-full); overflow: hidden; gap: 2px; }
.cb-seg { min-width: 4px; }
.cb-legend { display: flex; flex-wrap: wrap; gap: 6px 16px; }
.cb-item { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-13); }
.cb-dot { width: 8px; height: 8px; border-radius: var(--radius-full); flex: none; }
.cb-lbl { color: var(--text-body); }
.cb-pct { color: var(--text-sub); font-variant-numeric: tabular-nums; }
  `],
})
export class HrmCategoryBar {
  readonly segments = input<HrmCategorySegment[]>([]);
  readonly showLegend = input(true);

  protected readonly segs = computed(() => {
    const items = this.segments();
    const total = items.reduce((s, i) => s + i.value, 0) || 1;
    return items.map((i, idx) => ({
      label: i.label,
      value: i.value,
      pct: Math.round((i.value / total) * 1000) / 10,
      // Mặc định xoay vòng bảng màu dữ liệu --data-1..10.
      color: i.color || `var(--data-${(idx % 10) + 1})`,
    }));
  });
}
